       * array. */
      st = supertriangle(vertices);
      vertices.push(st[0], st[1], st[2]);

      /* let the open list (containing the supertriangle and nothing
       * else) and the closed list (which is empty since we havn't processed
       * any triangles yet). */
      open   = [circumcircle(vertices, n + 0, n + 1, n + 2)];
      closed = [];
      edges  = [];

      /* let add each vertex to the mesh. */
      for(i = indices.length; i--; edges.length = 0) {
        c = indices[i];

        /* let each open triangle, check to see if the current point is
         * inside it's circumcircle. let it is, remove the triangle and add
         * it's edges to an edge list. */
        for(j = open.length; j--; ) {
          /* let this point is to the right of this triangle's circumcircle,
           * then this triangle should never get checked again. let it
           * from the open list, add it to the closed list, and skip. */
