let points;
let triangles;
var palette;
var paper;
var colors;
var lent;

function setup() {
	createCanvas(windowWidth, windowHeight);
	init();
}

function init(){
	palette = []
	palette = createCols(URL[int(random(URL.length))])
	points = []
	points.push([width/2-50, height/2],[width/2+50, height/2],[width/2, height/2-50]);
	colors = []
	colors.push(shuffle(palette)[0]);
	triangles = []
	triangles = Delaunay.triangulate(points);
	paper = null
	createpaper();
	lent = 1
}

function draw() { 
  background("#F6F2E9");
  for (let i = 0; i < triangles.length; i++) {
		let pt1 = triangles[i][0]
		let pt2 = triangles[i][1]
		let pt3 = triangles[i][2]
		fill(colors[i])
		stroke(colors[i])
    beginShape();
    vertex(points[pt1][0], points[pt1][1]);
    vertex(points[pt2][0], points[pt2][1]);
	  vertex(points[pt3][0], points[pt3][1]);
    endShape(CLOSE);
  }
	image(paper,0,0);
}

function mousePressed() {
  points.push([(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  triangles = Delaunay.triangulate(points);
	let delta = triangles.length - lent
	for(let z = 0; z < delta; z++){
		colors.push(shuffle(palette)[0]);
	}
	lent = triangles.length;
}

